import { useCallback, useEffect, useMemo, useState, type ChangeEvent } from 'react';
import { invoke } from '@tauri-apps/api/core';
import type { AgentCommand, ContainerBackend, DbClient, FileEntry, MachineIdentity, ProcessInfo, RemoteConfig, RuntimeDetection } from './contracts';
import { connectionLabel, initialOverviewState, offlineOverviewState, onlineOverviewState, type AgentStatus } from './agentOverviewState';

type Section='overview'|'projects'|'services'|'runtimes'|'processes'|'containers'|'database'|'files'|'terminal'|'network'|'remote';
const DESKTOP_CAPABILITIES=['projects','services','runtimes','processes','containers','database','advanced_db_models','database_jobs','files','terminal','network','remote','core_health'] as const;
const nav:[Section,string,string][]=[
 ['overview','Overview','⌂'],['projects','Projects','◇'],['services','Services','◉'],['runtimes','Runtimes','⌘'],['processes','Processes','◫'],['containers','Containers','⬡'],['database','Database Studio','▦'],['files','Files','▤'],['terminal','Terminal','>_'],['network','Networking','◎'],['remote','Remote','↗']
];
async function call<T>(command:AgentCommand,params:Record<string,unknown>={}):Promise<T>{return invoke<T>('agent_call',{command,params});}
function Badge({ok,label}:{ok:boolean;label:string}){return <span className={ok?'badge ok':'badge muted'}><i/>{label}</span>}
function Stat({label,value,hint}:{label:string;value:string|number;hint?:string}){return <div className="stat"><span>{label}</span><strong>{value}</strong>{hint&&<small>{hint}</small>}</div>}
function JsonView({value}:{value:unknown}){return <pre className="json">{JSON.stringify(value,null,2)}</pre>}

export default function App(){
 const [section,setSection]=useState<Section>('overview');
 const [overview,setOverview]=useState(initialOverviewState);const {connection,machine,status,runtimes,processes,backends,remote,coreError,optionalErrors}=overview;const [busy,setBusy]=useState(false);
 const refresh=useCallback(async()=>{setBusy(true);try{const[m,s]=await Promise.all([call<MachineIdentity>('machine'),call<AgentStatus>('status')]);const[r,p,c,rem]=await Promise.allSettled([call<RuntimeDetection[]>('runtime.list'),call<ProcessInfo[]>('process.list'),call<ContainerBackend[]>('container.backends'),call<RemoteConfig>('remote.status')]);setOverview(onlineOverviewState(m,s,{runtimes:r,processes:p,backends:c,remote:rem}));}catch(e){setOverview(offlineOverviewState(e));}finally{setBusy(false)}},[]);
 useEffect(()=>{void refresh()},[refresh]);const installed=useMemo(()=>runtimes.filter(r=>r.installed).length,[runtimes]);
 return <div className="shell"><aside><div className="brand"><div className="mark">V</div><div><b>VSN</b><span>Dev Platform</span></div></div><nav>{nav.map(([id,label,icon])=><button key={id} className={section===id?'active':''} onClick={()=>setSection(id)}><span>{icon}</span>{label}</button>)}</nav><div className="asideFoot"><Badge ok={connection==='online'&&!!status?.health?.healthy} label={connectionLabel(connection)}/><small>Local-first · v0.38.1</small></div></aside>
 <main><header><div><p className="eyebrow">LOCAL + REMOTE DEVELOPMENT CONTROL PLANE</p><h1>{nav.find(n=>n[0]===section)?.[1]}</h1></div><div className="headerActions"><div className="machineChip"><span className={connection==='online'?'dot':connection==='offline'?'dot offline':'dot connecting'}/><div><b>{connection==='offline'?'Agent unavailable':machine?.display_name??'Connecting…'}</b><small>{connection==='offline'?'Authenticated bridge offline':machine?.os??'—'}</small></div></div><button className="primary" disabled={busy} onClick={()=>void refresh()}>{busy?'Refreshing…':'Refresh'}</button></div></header>{coreError&&<div className="error">{coreError}</div>}{optionalErrors.length>0&&<div className="warning">Partial refresh: {optionalErrors.join(' · ')}</div>}
 <div className="content"><section className="panel"><div className="panelHead"><div><span className="kicker">Desktop source coverage</span><h3>{DESKTOP_CAPABILITIES.length} operator capabilities</h3></div><Badge ok label="Explicit coverage"/></div><p className="hint">Projects, services, runtimes, process/container management, relational and advanced databases, jobs, files, terminal, networking and remote administration are explicitly surfaced. Native installer/signing acceptance is tracked under P30.</p></section>
 {section==='overview'&&<Overview machine={machine} status={status} installed={installed} processes={processes.length} backends={backends} remote={remote}/>} 
 {section==='projects'&&<Projects/>}{section==='services'&&<Services/>}{section==='runtimes'&&<Runtimes rows={runtimes}/>} {section==='processes'&&<Processes rows={processes}/>} {section==='containers'&&<><Containers rows={backends}/><ContainerRegistry/></>} {section==='database'&&<><DatabaseStudio/><DatabaseAdvanced/><AdvancedModelAnalyzer/><DatabaseJobs/><NativePostgresJobs/></>}{section==='files'&&<FilesPanel/>}{section==='terminal'&&<TerminalPanel/>}{section==='network'&&<Networking/>}{section==='remote'&&<RemotePanel config={remote}/>}</div></main></div>
}

function Overview({machine,status,installed,processes,backends,remote}:{machine:MachineIdentity|null;status:any;installed:number;processes:number;backends:ContainerBackend[];remote:RemoteConfig|null}){return <><section className="hero"><div><span className="kicker">Machine workspace</span><h2>{machine?.display_name??'VSN machine'}</h2><p>Runtimes, projects, databases, services, files and remote control stay behind the authenticated VSN Agent execution boundary.</p><div className="heroBadges"><Badge ok={!!status?.security?.device_identity_ready} label="Device identity"/><Badge ok={!!status?.security?.ipc_secret_ready} label="Authenticated IPC"/><Badge ok={!!remote?.enabled} label={remote?.enabled?'Remote enabled':'Remote disabled'}/></div></div><div className="deviceId"><span>DEVICE ID</span><code>{machine?.device_id??'—'}</code></div></section><div className="stats"><Stat label="Detected runtimes" value={installed} hint="PATH + VSN registry"/><Stat label="Visible processes" value={processes} hint="Current snapshot"/><Stat label="Container engines" value={backends.filter(b=>b.installed).length} hint="Docker / Podman"/><Stat label="Remote channel" value={remote?.enabled?'ON':'OFF'} hint={remote?.control_plane_url??'Not configured'}/></div><section className="panel"><div className="panelHead"><div><span className="kicker">Security boundary</span><h3>Local agent posture</h3></div></div><div className="grid2"><div className="info"><span>Secure store</span><b>{status?.security?.secure_store??'—'}</b></div><div className="info"><span>Agent health</span><b>{status?.health?.detail??'—'}</b></div></div></section></>}

function Projects(){const[root,setRoot]=useState('');const[roots,setRoots]=useState<string[]>([]);const[path,setPath]=useState('');const[result,setResult]=useState<any>(null);const[previewPort,setPreviewPort]=useState('8000');const[previewPath,setPreviewPath]=useState('/');const[previewMethod,setPreviewMethod]=useState('GET');const[previewBody,setPreviewBody]=useState('');const[err,setErr]=useState('');async function load(){try{setRoots(await call<string[]>('workspace.roots'))}catch(e){setErr(String(e))}}useEffect(()=>{void load()},[]);async function rootAction(action:'add'|'remove'){setErr('');try{await call(action==='add'?'workspace.add':'workspace.remove',{path:root});await load()}catch(e){setErr(String(e))}}async function inspect(){setErr('');try{setResult({project:await call('project.detect',{path}),dependencies:await call('project.dependencies',{path})})}catch(e){setErr(String(e))}}async function preview(){setErr('');try{setResult(await call('preview.fetch',{port:Number(previewPort),path:previewPath,method:'GET'}))}catch(e){setErr(String(e))}}async function previewRequest(){setErr('');try{const bytes=new TextEncoder().encode(previewBody);let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);setResult(await call('preview.request',{port:Number(previewPort),path:previewPath,method:previewMethod,headers:{'content-type':'application/json'},body_base64:btoa(binary)}))}catch(e){setErr(String(e))}}return <><section className="panel"><div className="panelHead"><div><span className="kicker">Workspace sandbox</span><h3>Project roots</h3></div><Badge ok={roots.length>0} label={`${roots.length} roots`}/></div><div className="formRow"><input value={root} onChange={(e:ChangeEvent<HTMLInputElement>)=>setRoot(e.target.value)} placeholder="Absolute workspace root"/><button className="primary" onClick={()=>void rootAction('add')}>Add</button><button className="ghost" onClick={()=>void rootAction('remove')}>Remove</button></div><div className="rootList">{roots.map(r=><code key={r}>{r}</code>)}</div></section><section className="panel"><div className="panelHead"><div><span className="kicker">Detection</span><h3>Inspect project</h3></div></div><div className="formRow"><input value={path} onChange={(e:ChangeEvent<HTMLInputElement>)=>setPath(e.target.value)} placeholder="Absolute project directory"/><button className="primary" onClick={()=>void inspect()}>Detect</button></div><div className="formGrid"><label>Preview port<input value={previewPort} onChange={(e:ChangeEvent<HTMLInputElement>)=>setPreviewPort(e.target.value)}/></label><label>Preview path<input value={previewPath} onChange={(e:ChangeEvent<HTMLInputElement>)=>setPreviewPath(e.target.value)}/></label><label>Local proxy method<select value={previewMethod} onChange={e=>setPreviewMethod(e.target.value)}><option>GET</option><option>HEAD</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option><option>OPTIONS</option></select></label></div><label className="stacked">Local proxy body<textarea value={previewBody} onChange={e=>setPreviewBody(e.target.value)} rows={4} placeholder="Optional UTF-8 body; local-only advanced preview request"/></label><div className="buttonRow"><button className="ghost" onClick={()=>void preview()}>Fetch private read-only preview</button><button className="primary" onClick={()=>void previewRequest()}>Send local advanced preview</button></div><p className="hint">Advanced preview supports bounded request bodies and filtered headers against 127.0.0.1 only. Mutation-capable preview.request is not in the remote signed-command allowlist.</p>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section></>}

function Services(){const[name,setName]=useState('VSN-');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');async function run(action:'status'|'start'|'stop'|'restart'){setErr('');try{setResult(action==='status'?await call('service.status',{name}):await call('service.action',{name,action}))}catch(e){setErr(String(e))}}return <section className="panel"><div className="panelHead"><div><span className="kicker">OS service boundary</span><h3>VSN-managed services</h3></div><Badge ok label="VSN-* mutations only"/></div><div className="formRow"><input value={name} onChange={(e:ChangeEvent<HTMLInputElement>)=>setName(e.target.value)} placeholder="VSN-Postgres"/><button className="primary" onClick={()=>void run('status')}>Status</button></div><div className="buttonRow"><button className="ghost" onClick={()=>void run('start')}>Start</button><button className="ghost" onClick={()=>void run('restart')}>Restart</button><button className="danger" onClick={()=>void run('stop')}>Stop</button></div>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section>}

function Runtimes({rows}:{rows:RuntimeDetection[]}){const[catalog,setCatalog]=useState('');const[runtime,setRuntime]=useState('php');const[version,setVersion]=useState('');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');async function run(action:'install'|'uninstall'){setErr('');try{setResult(action==='install'?await call('runtime.install',{catalog,runtime,version}):await call('runtime.uninstall',{runtime,version}))}catch(e){setErr(String(e))}}async function audit(){setErr('');try{setResult(await call('runtime.audit',{}))}catch(e){setErr(String(e))}}return <><section className="panel"><div className="panelHead"><div><span className="kicker">Provider-driven</span><h3>Runtime inventory</h3></div><span>{rows.filter(r=>r.installed).length}/{rows.length} detected</span></div><div className="cards">{rows.map(r=><article className="runtime" key={r.id}><div className="runtimeIcon">{r.id.slice(0,2).toUpperCase()}</div><div><h4>{r.id}</h4><p>{r.version??'Not installed on PATH'}</p></div><Badge ok={r.installed} label={r.installed?'Available':'Missing'}/></article>)}</div></section><section className="panel"><div className="panelHead"><div><span className="kicker">VSN managed runtime</span><h3>Install / uninstall</h3></div></div><div className="formGrid"><label>Catalog path<input value={catalog} onChange={(e:ChangeEvent<HTMLInputElement>)=>setCatalog(e.target.value)} placeholder="C:\catalogs\runtime.json"/></label><label>Runtime<input value={runtime} onChange={(e:ChangeEvent<HTMLInputElement>)=>setRuntime(e.target.value)}/></label><label>Version<input value={version} onChange={(e:ChangeEvent<HTMLInputElement>)=>setVersion(e.target.value)} placeholder="8.4.0"/></label></div><div className="buttonRow"><button className="primary" onClick={()=>void run('install')}>Install verified artifact</button><button className="ghost" onClick={()=>void run('uninstall')}>Uninstall</button><button className="ghost" onClick={()=>void audit()}>Audit registry</button></div>{err&&<div className="error">{err}</div>}{result&&<JsonView value={result}/>}</section></>}
function Processes({rows}:{rows:ProcessInfo[]}){return <section className="panel"><div className="panelHead"><div><span className="kicker">Machine</span><h3>Process snapshot</h3></div><span>{rows.length} shown</span></div><div className="table"><div className="tr th"><span>PID</span><span>Name</span><span>Command</span></div>{rows.map(p=><div className="tr" key={p.pid}><code>{p.pid}</code><b>{p.name}</b><span className="truncate">{p.command??'—'}</span></div>)}</div></section>}
function Containers({rows}:{rows:ContainerBackend[]}){return <div className="cards">{rows.map(r=><article className="panel engine" key={r.id}><span className="kicker">Container backend</span><h3>{r.id}</h3><p>{r.version??'Executable not detected'}</p><Badge ok={!!r.daemon_reachable} label={r.daemon_reachable?'Daemon reachable':r.installed?'Installed / daemon unavailable':'Not installed'}/></article>)}</div>}

function DatabaseStudio(){const[clients,setClients]=useState<DbClient[]>([]);const[engine,setEngine]=useState('postgresql');const[host,setHost]=useState('127.0.0.1');const[port,setPort]=useState('5432');const[user,setUser]=useState('');const[database,setDatabase]=useState('');const[credential,setCredential]=useState('');const[sql,setSql]=useState('SELECT 1');const[result,setResult]=useState<any>(null);const[sqlite,setSqlite]=useState('');const[sqliteEntity,setSqliteEntity]=useState('users');const[sqliteMutation,setSqliteMutation]=useState('{"values":{"name":"Ada"},"filter":{}}');const[err,setErr]=useState('');const[nativePg,setNativePg]=useState('host=localhost user=postgres dbname=postgres');const[nativeSchema,setNativeSchema]=useState('public');const[nativeTable,setNativeTable]=useState('');const[mysqlUrl,setMysqlUrl]=useState('mysql://root@localhost/mysql');const[mysqlDatabase,setMysqlDatabase]=useState('mysql');const[mysqlTable,setMysqlTable]=useState('user');const[redisUrl,setRedisUrl]=useState('redis://localhost:6379/0');const[redisKey,setRedisKey]=useState('');const[redisValue,setRedisValue]=useState('');const[redisTtl,setRedisTtl]=useState('');const[nativeMutation,setNativeMutation]=useState('{"values":{"name":"Ada"},"filter":{}}');useEffect(()=>{call<DbClient[]>('database.cli.detect').then(setClients).catch(e=>setErr(String(e)))},[]);function connection(){return{engine,host:host||null,port:port?Number(port):null,user:user||null,database:database||null,credential_file:credential||null,service:null}}async function inspect(){setErr('');try{setResult(await call('database.cli.inspect',{connection:connection()}))}catch(e){setErr(String(e))}}async function query(){setErr('');try{setResult(await call('database.cli.query',{connection:connection(),sql}))}catch(e){setErr(String(e))}}async function sqliteAction(action:'inspect'|'browse'|'indexes'|'relations'|'stats'|'insert'|'update'|'delete'){setErr('');try{if(action==='inspect'){setResult(await call('database.sqlite.inspect',{path:sqlite}));return}if(action==='browse'){setResult(await call('database.sqlite.browse',{path:sqlite,entity:sqliteEntity,limit:100,offset:0}));return}if(action==='indexes'||action==='relations'||action==='stats'){setResult(await call(`database.sqlite.${action}`,{path:sqlite,entity:sqliteEntity}));return}const request=JSON.parse(sqliteMutation);setResult(await call(`database.sqlite.${action}`,{path:sqlite,entity:sqliteEntity,request}))}catch(e){setErr(String(e))}}async function nativePgAction(action:'inspect'|'browse'|'query'|'indexes'|'relations'|'stats'|'insert'|'update'|'delete'){setErr('');try{if(action==='inspect')setResult(await call('database.native.postgres.inspect',{connection_string:nativePg}));else if(action==='browse')setResult(await call('database.native.postgres.browse',{connection_string:nativePg,schema:nativeSchema,table:nativeTable,limit:100,offset:0}));else if(action==='query')setResult(await call('database.native.postgres.query',{connection_string:nativePg,sql}));else if(action==='indexes'||action==='relations'||action==='stats')setResult(await call(`database.native.postgres.${action}`,{connection_string:nativePg,schema:nativeSchema,table:nativeTable}));else setResult(await call(`database.native.postgres.${action}`,{connection_string:nativePg,schema:nativeSchema,table:nativeTable,request:JSON.parse(nativeMutation)}))}catch(e){setErr(String(e))}}async function nativeMysqlAction(action:'inspect'|'browse'|'query'|'indexes'|'relations'|'stats'|'insert'|'update'|'delete'){setErr('');try{if(action==='inspect')setResult(await call('database.native.mysql.inspect',{url:mysqlUrl}));else if(action==='browse')setResult(await call('database.native.mysql.browse',{url:mysqlUrl,database:mysqlDatabase,table:mysqlTable,limit:100,offset:0}));else if(action==='query')setResult(await call('database.native.mysql.query',{url:mysqlUrl,sql}));else if(action==='indexes'||action==='relations'||action==='stats')setResult(await call(`database.native.mysql.${action}`,{url:mysqlUrl,database:mysqlDatabase,table:mysqlTable}));else setResult(await call(`database.native.mysql.${action}`,{url:mysqlUrl,database:mysqlDatabase,table:mysqlTable,request:JSON.parse(nativeMutation)}))}catch(e){setErr(String(e))}}async function nativeRedisAction(action:'inspect'|'get'|'set'|'delete'){setErr('');try{if(action==='inspect')setResult(await call('database.native.redis.inspect',{url:redisUrl}));else if(action==='get')setResult(await call('database.native.redis.get',{url:redisUrl,key:redisKey}));else if(action==='set')setResult(await call('database.native.redis.set',{url:redisUrl,key:redisKey,value:redisValue,ttl_seconds:redisTtl?Number(redisTtl):null}));else setResult(await call('database.native.redis.delete',{url:redisUrl,key:redisKey}))}catch(e){setErr(String(e))}}return <><section className="panel"><div className="panelHead"><div><span className="kicker">Native client adapters</span><h3>Database clients</h3></div><span>{clients.filter(c=>c.available).length}/{clients.length} available</span></div><div className="cards">{clients.map(c=><article className="runtime" key={c.engine}><div className="runtimeIcon">DB</div><div><h4>{c.engine}</h4><p>{c.version??c.executable??'Not detected'}</p></div><Badge ok={c.available} label={c.available?'Available':'Missing'}/></article>)}</div></section><section className="panel"><div className="panelHead"><div><span className="kicker">Universal DB Studio</span><h3>Read-only external DB inspection</h3></div><Badge ok label="No password argv"/></div><div className="formGrid cols3"><label>Engine<select value={engine} onChange={e=>setEngine(e.target.value)}><option value="postgresql">PostgreSQL</option><option value="mysql">MySQL</option><option value="mariadb">MariaDB</option><option value="mongo">MongoDB</option><option value="redis">Redis</option></select></label><label>Host<input value={host} onChange={e=>setHost(e.target.value)}/></label><label>Port<input value={port} onChange={e=>setPort(e.target.value)}/></label><label>User<input value={user} onChange={e=>setUser(e.target.value)}/></label><label>Database<input value={database} onChange={e=>setDatabase(e.target.value)}/></label><label>Credential config file<input value={credential} onChange={e=>setCredential(e.target.value)} placeholder="Optional .pgpass / defaults-extra-file"/></label></div><div className="buttonRow"><button className="primary" onClick={()=>void inspect()}>Inspect</button></div><label className="stacked">Read-only SQL<textarea value={sql} onChange={e=>setSql(e.target.value)} rows={5}/></label><button className="ghost" disabled={engine==='mongo'||engine==='redis'} onClick={()=>void query()}>Run read-only query</button><p className="hint">PostgreSQL/MySQL/MariaDB query mode accepts read-only single-statement SELECT/SHOW/DESCRIBE only. MongoDB and Redis baseline exposes introspection only. Credentials are never accepted as password command-line arguments.</p></section><section className="panel"><div className="panelHead"><div><span className="kicker">Native Rust drivers</span><h3>PostgreSQL + MySQL + Redis</h3></div><Badge ok label="Direct protocol clients"/></div><div className="formGrid"><label>PostgreSQL connection<input value={nativePg} onChange={e=>setNativePg(e.target.value)} placeholder="host=localhost user=postgres dbname=postgres"/></label><label>Schema<input value={nativeSchema} onChange={e=>setNativeSchema(e.target.value)}/></label><label>Table<input value={nativeTable} onChange={e=>setNativeTable(e.target.value)}/></label></div><div className="buttonRow"><button className="primary" onClick={()=>void nativePgAction('inspect')}>Inspect PostgreSQL</button><button className="ghost" disabled={!nativeTable} onClick={()=>void nativePgAction('browse')}>Browse table</button><button className="ghost" onClick={()=>void nativePgAction('query')}>Run read-only SQL</button><button className="ghost" disabled={!nativeTable} onClick={()=>void nativePgAction('indexes')}>Indexes</button><button className="ghost" disabled={!nativeTable} onClick={()=>void nativePgAction('relations')}>Relations</button><button className="ghost" disabled={!nativeTable} onClick={()=>void nativePgAction('stats')}>Stats</button></div><div className="formGrid"><label>MySQL URL<input value={mysqlUrl} onChange={e=>setMysqlUrl(e.target.value)}/></label><label>MySQL database<input value={mysqlDatabase} onChange={e=>setMysqlDatabase(e.target.value)}/></label><label>MySQL table<input value={mysqlTable} onChange={e=>setMysqlTable(e.target.value)}/></label></div><div className="buttonRow"><button className="primary" onClick={()=>void nativeMysqlAction('inspect')}>Inspect MySQL</button><button className="ghost" disabled={!mysqlTable} onClick={()=>void nativeMysqlAction('browse')}>Browse MySQL</button><button className="ghost" onClick={()=>void nativeMysqlAction('query')}>Run MySQL read-only SQL</button><button className="ghost" disabled={!mysqlTable} onClick={()=>void nativeMysqlAction('indexes')}>Indexes</button><button className="ghost" disabled={!mysqlTable} onClick={()=>void nativeMysqlAction('relations')}>Relations</button><button className="ghost" disabled={!mysqlTable} onClick={()=>void nativeMysqlAction('stats')}>Stats</button></div><label className="stacked">Structured mutation JSON<textarea value={nativeMutation} onChange={e=>setNativeMutation(e.target.value)} rows={5}/></label><div className="buttonRow"><button className="primary" disabled={!nativeTable} onClick={()=>void nativePgAction('insert')}>PG Insert</button><button className="ghost" disabled={!nativeTable} onClick={()=>void nativePgAction('update')}>PG Update</button><button className="danger" disabled={!nativeTable} onClick={()=>void nativePgAction('delete')}>PG Delete</button><button className="primary" disabled={!mysqlTable} onClick={()=>void nativeMysqlAction('insert')}>MySQL Insert</button><button className="ghost" disabled={!mysqlTable} onClick={()=>void nativeMysqlAction('update')}>MySQL Update</button><button className="danger" disabled={!mysqlTable} onClick={()=>void nativeMysqlAction('delete')}>MySQL Delete</button></div><div className="formGrid"><label>Redis URL<input value={redisUrl} onChange={e=>setRedisUrl(e.target.value)}/></label><label>Redis key<input value={redisKey} onChange={e=>setRedisKey(e.target.value)}/></label><label>Redis value<input value={redisValue} onChange={e=>setRedisValue(e.target.value)}/></label><label>TTL seconds<input value={redisTtl} onChange={e=>setRedisTtl(e.target.value)}/></label></div><div className="buttonRow"><button className="primary" onClick={()=>void nativeRedisAction('inspect')}>Inspect Redis</button><button className="ghost" disabled={!redisKey} onClick={()=>void nativeRedisAction('get')}>Read key</button><button className="ghost" disabled={!redisKey} onClick={()=>void nativeRedisAction('set')}>Set string</button><button className="danger" disabled={!redisKey} onClick={()=>void nativeRedisAction('delete')}>Delete key</button></div><p className="hint">Structured PostgreSQL/MySQL mutations bind values instead of concatenating them; update/delete require non-empty equality filters. Native database network policy remains conservative, and remote DB mutation is not exposed through the signed remote command allowlist.</p></section><section className="panel"><div className="panelHead"><div><span className="kicker">Embedded DB Studio</span><h3>SQLite browse + structured CRUD</h3></div><Badge ok label="Parameterized mutations"/></div><div className="formGrid"><label>SQLite file<input value={sqlite} onChange={e=>setSqlite(e.target.value)} placeholder="Absolute .sqlite/.db file"/></label><label>Table / view<input value={sqliteEntity} onChange={e=>setSqliteEntity(e.target.value)} placeholder="users"/></label></div><div className="buttonRow"><button className="primary" onClick={()=>void sqliteAction('inspect')}>Inspect DB</button><button className="ghost" onClick={()=>void sqliteAction('browse')}>Browse 100</button><button className="ghost" onClick={()=>void sqliteAction('indexes')}>Indexes</button><button className="ghost" onClick={()=>void sqliteAction('relations')}>Relations</button><button className="ghost" onClick={()=>void sqliteAction('stats')}>Stats</button></div><label className="stacked">Mutation JSON<textarea value={sqliteMutation} onChange={e=>setSqliteMutation(e.target.value)} rows={6}/></label><div className="buttonRow"><button className="primary" onClick={()=>void sqliteAction('insert')}>Insert</button><button className="ghost" onClick={()=>void sqliteAction('update')}>Update</button><button className="danger" onClick={()=>void sqliteAction('delete')}>Delete</button></div><p className="hint">Update/delete require a non-empty equality filter. Mutation values are bound as parameters; Desktop does not construct raw SQL values.</p>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section></>}

function DatabaseAdvanced(){const[mongoUrl,setMongoUrl]=useState('mongodb://localhost:27017');const[mongoDb,setMongoDb]=useState('test');const[mongoCollection,setMongoCollection]=useState('users');const[mongoFilter,setMongoFilter]=useState('{}');const[mongoMutation,setMongoMutation]=useState('{"values":{"name":"Ada"},"filter":{}}');const[pgTls,setPgTls]=useState('host=db.example.com user=postgres dbname=postgres');const[pgCa,setPgCa]=useState('');const[mysqlTls,setMysqlTls]=useState('mysql://user@db.example.com/app');const[mysqlCa,setMysqlCa]=useState('');const[sql,setSql]=useState('SELECT 1');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');async function mongo(action:'inspect'|'browse'|'indexes'|'stats'|'insert'|'update'|'delete'){setErr('');try{const base={url:mongoUrl,database:mongoDb,collection:mongoCollection};if(action==='inspect')setResult(await call('database.native.mongo.inspect',{url:mongoUrl,database:mongoDb||null}));else if(action==='browse')setResult(await call('database.native.mongo.browse',{...base,limit:100,offset:0,filter:JSON.parse(mongoFilter||'{}')}));else if(action==='indexes'||action==='stats')setResult(await call(`database.native.mongo.${action}`,base));else setResult(await call(`database.native.mongo.${action}`,{...base,request:JSON.parse(mongoMutation)}))}catch(e){setErr(String(e))}}async function pg(action:'inspect'|'browse'|'query'){setErr('');try{const connection={connection_string:pgTls,root_ca_pem_path:pgCa};if(action==='inspect')setResult(await call('database.tls.postgres.inspect',{connection}));else if(action==='browse')setResult(await call('database.tls.postgres.browse',{connection,schema:'public',table:mongoCollection,limit:100,offset:0}));else setResult(await call('database.tls.postgres.query',{connection,sql}))}catch(e){setErr(String(e))}}async function mysql(action:'inspect'|'browse'|'query'){setErr('');try{const connection={url:mysqlTls,root_ca_path:mysqlCa};if(action==='inspect')setResult(await call('database.tls.mysql.inspect',{connection}));else if(action==='browse')setResult(await call('database.tls.mysql.browse',{connection,database:mongoDb,table:mongoCollection,limit:100,offset:0}));else setResult(await call('database.tls.mysql.query',{connection,sql}))}catch(e){setErr(String(e))}}return <><section className="panel"><div className="panelHead"><div><span className="kicker">Native document database</span><h3>MongoDB Studio</h3></div><Badge ok label="Local or SRV/TLS policy"/></div><div className="formGrid"><label>MongoDB URL<input value={mongoUrl} onChange={e=>setMongoUrl(e.target.value)}/></label><label>Database<input value={mongoDb} onChange={e=>setMongoDb(e.target.value)}/></label><label>Collection<input value={mongoCollection} onChange={e=>setMongoCollection(e.target.value)}/></label></div><label className="stacked">Browse filter JSON<textarea value={mongoFilter} onChange={e=>setMongoFilter(e.target.value)} rows={3}/></label><div className="buttonRow"><button className="primary" onClick={()=>void mongo('inspect')}>Inspect Mongo</button><button className="ghost" onClick={()=>void mongo('browse')}>Browse</button><button className="ghost" onClick={()=>void mongo('indexes')}>Indexes</button><button className="ghost" onClick={()=>void mongo('stats')}>Stats</button></div><label className="stacked">Structured mutation JSON<textarea value={mongoMutation} onChange={e=>setMongoMutation(e.target.value)} rows={5}/></label><div className="buttonRow"><button className="primary" onClick={()=>void mongo('insert')}>Insert</button><button className="ghost" onClick={()=>void mongo('update')}>Update</button><button className="danger" onClick={()=>void mongo('delete')}>Delete</button></div><p className="hint">Non-loopback plaintext mongodb:// is rejected. Remote Mongo mutations are not part of the signed remote-command allowlist.</p></section><section className="panel"><div className="panelHead"><div><span className="kicker">Verified database TLS</span><h3>PostgreSQL / MySQL CA profiles</h3></div><Badge ok label="CA validation retained"/></div><div className="formGrid"><label>PostgreSQL connection<input value={pgTls} onChange={e=>setPgTls(e.target.value)}/></label><label>PostgreSQL root CA<input value={pgCa} onChange={e=>setPgCa(e.target.value)} placeholder="Absolute PEM path"/></label><label>MySQL URL<input value={mysqlTls} onChange={e=>setMysqlTls(e.target.value)}/></label><label>MySQL root CA<input value={mysqlCa} onChange={e=>setMysqlCa(e.target.value)} placeholder="Absolute PEM/DER path"/></label></div><label className="stacked">Read-only SQL<textarea value={sql} onChange={e=>setSql(e.target.value)} rows={4}/></label><div className="buttonRow"><button className="primary" onClick={()=>void pg('inspect')}>PG TLS Inspect</button><button className="ghost" onClick={()=>void pg('query')}>PG TLS Query</button><button className="primary" onClick={()=>void mysql('inspect')}>MySQL TLS Inspect</button><button className="ghost" onClick={()=>void mysql('query')}>MySQL TLS Query</button></div><p className="hint">CA files must be absolute local files. Certificate validation and hostname verification are not disabled by these profiles.</p>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section></>}

function FilesPanel(){const[path,setPath]=useState('');const[entries,setEntries]=useState<FileEntry[]>([]);const[file,setFile]=useState('');const[content,setContent]=useState('');const[opPath,setOpPath]=useState('');const[destination,setDestination]=useState('');const[transferId,setTransferId]=useState('');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');async function list(){setErr('');try{setEntries(await call<FileEntry[]>('files.list',{path}))}catch(e){setErr(String(e))}}async function read(){setErr('');try{const r:any=await call('files.read',{path:file});setContent(r.content??'');setResult(r)}catch(e){setErr(String(e))}}async function write(){setErr('');try{setResult(await call('files.write',{path:file,content}))}catch(e){setErr(String(e))}}async function mutate(action:'mkdir'|'move'|'delete'){setErr('');try{if(action==='mkdir')setResult(await call('files.mkdir',{path:opPath}));else if(action==='move')setResult(await call('files.move',{source:opPath,destination}));else setResult(await call('files.delete',{path:opPath,recursive:true}));await list()}catch(e){setErr(String(e))}}async function digest(){setErr('');try{setResult(await call('files.digest',{path:file}))}catch(e){setErr(String(e))}}async function uploadStatus(){setErr('');try{setResult(await call('files.binary.status',{path:file,transfer_id:transferId}))}catch(e){setErr(String(e))}}return <><section className="panel"><div className="panelHead"><div><span className="kicker">Workspace-contained</span><h3>File browser</h3></div><Badge ok label="Root sandbox enforced"/></div><div className="formRow"><input value={path} onChange={e=>setPath(e.target.value)} placeholder="Workspace directory"/><button className="primary" onClick={()=>void list()}>List</button></div><div className="fileList">{entries.map(e=><button key={e.path} onClick={()=>{if(e.is_dir){setPath(e.path);setOpPath(e.path)}else{setFile(e.path);setOpPath(e.path)}}}><b>{e.is_dir?'DIR':'FILE'}</b><span>{e.name}</span><small>{e.is_dir?'':`${e.size} B`}</small></button>)}</div></section><section className="panel"><div className="panelHead"><div><span className="kicker">Filesystem operations</span><h3>Create / move / delete</h3></div><Badge ok label="Workspace only"/></div><div className="formGrid"><label>Source / new path<input value={opPath} onChange={e=>setOpPath(e.target.value)} placeholder="Absolute path inside a workspace"/></label><label>Move destination<input value={destination} onChange={e=>setDestination(e.target.value)} placeholder="Absolute destination inside a workspace"/></label></div><div className="buttonRow"><button className="primary" onClick={()=>void mutate('mkdir')}>Create directory</button><button className="ghost" onClick={()=>void mutate('move')}>Move</button><button className="danger" onClick={()=>void mutate('delete')}>Delete recursively</button></div><p className="hint">Configured workspace roots themselves cannot be moved or deleted. Binary transfer continues to use resumable bounded chunks and optional final SHA-256 verification.</p></section><section className="panel"><div className="formRow"><input value={file} onChange={e=>setFile(e.target.value)} placeholder="Workspace file"/><button className="ghost" onClick={()=>void read()}>Read text</button><button className="ghost" onClick={()=>void digest()}>SHA-256</button></div><div className="formRow"><input value={transferId} onChange={e=>setTransferId(e.target.value)} placeholder="Binary upload transfer ID"/><button className="ghost" disabled={!transferId||!file} onClick={()=>void uploadStatus()}>Upload offset/status</button></div><textarea className="editor" value={content} onChange={e=>setContent(e.target.value)} rows={18}/><button className="primary" onClick={()=>void write()}>Atomic write</button>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section></>}

function TerminalPanel(){const[cwd,setCwd]=useState('');const[program,setProgram]=useState('php');const[args,setArgs]=useState('["-a"]');const[session,setSession]=useState('');const[input,setInput]=useState('');const[output,setOutput]=useState('');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');const[pty,setPty]=useState(true);const[rows,setRows]=useState('30');const[cols,setCols]=useState('120');const[scrollbacks,setScrollbacks]=useState<any[]>([]);const[scrollId,setScrollId]=useState('');const[scrollOffset,setScrollOffset]=useState(0);const[scrollText,setScrollText]=useState('');function parsedArgs(){const value=JSON.parse(args);if(!Array.isArray(value))throw new Error('Args must be a JSON array');return value as string[]}async function run(){setErr('');try{setResult(await call('terminal.exec',{cwd,program,args:parsedArgs(),env:{},timeout_ms:30000}))}catch(e){setErr(String(e))}}async function startSession(){setErr('');try{const r:any=await call(pty?'terminal.pty.start':'terminal.session.start',pty?{cwd,program,args:parsedArgs(),env:{},rows:Number(rows),cols:Number(cols)}:{cwd,program,args:parsedArgs(),env:{}});setSession(r.session_id);setResult(r)}catch(e){setErr(String(e))}}async function write(){setErr('');try{setResult(await call(pty?'terminal.pty.write':'terminal.session.write',{session_id:session,input}));setInput('')}catch(e){setErr(String(e))}}async function read(){setErr('');try{const r:any=await call(pty?'terminal.pty.read-wait':'terminal.session.read-wait',{session_id:session,max_bytes:65536,wait_ms:1000});setOutput(v=>v+(r.output??'')+(r.stdout??'')+(r.stderr??''));setResult(r)}catch(e){setErr(String(e))}}async function resize(){setErr('');try{setResult(await call('terminal.pty.resize',{session_id:session,rows:Number(rows),cols:Number(cols)}))}catch(e){setErr(String(e))}}async function stop(){setErr('');try{setResult(await call(pty?'terminal.pty.stop':'terminal.session.stop',{session_id:session}))}catch(e){setErr(String(e))}}async function loadScrollbacks(){setErr('');try{const rows=await call<any[]>('terminal.pty.scrollback.list',{});setScrollbacks(rows);if(!scrollId&&rows[0])setScrollId(rows[0].session_id)}catch(e){setErr(String(e))}}async function readScrollback(){if(!scrollId)return;setErr('');try{const chunk=await call<any>('terminal.pty.scrollback.read',{session_id:scrollId,offset:scrollOffset,max_bytes:262144});const raw=atob(chunk.payload_base64||'');const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));setScrollText(prev=>prev+new TextDecoder().decode(bytes));setScrollOffset(Number(chunk.next_offset||scrollOffset));setResult(chunk)}catch(e){setErr(String(e))}}async function removeScrollback(){if(!scrollId)return;setErr('');try{await call('terminal.pty.scrollback.remove',{session_id:scrollId});setScrollText('');setScrollOffset(0);setScrollId('');await loadScrollbacks()}catch(e){setErr(String(e))}}return <><section className="panel"><div className="panelHead"><div><span className="kicker">Agent terminal</span><h3>{pty?'Native PTY session':'Process-pipe session'}</h3></div><Badge ok={!!session} label={session||'No session'}/></div><div className="formGrid"><label>Workspace cwd<input value={cwd} onChange={e=>setCwd(e.target.value)}/></label><label>Program<input value={program} onChange={e=>setProgram(e.target.value)}/></label><label className="check"><input type="checkbox" checked={pty} onChange={e=>setPty(e.target.checked)}/> Use PTY / ConPTY backend</label><label>Rows<input value={rows} onChange={e=>setRows(e.target.value)}/></label><label>Columns<input value={cols} onChange={e=>setCols(e.target.value)}/></label></div><label className="stacked">Arguments JSON<textarea value={args} onChange={e=>setArgs(e.target.value)} rows={3}/></label><div className="buttonRow"><button className="primary" onClick={()=>void startSession()}>Start session</button><button className="ghost" onClick={()=>void run()}>One-shot exec</button><button className="ghost" disabled={!session||!pty} onClick={()=>void resize()}>Resize PTY</button><button className="danger" disabled={!session} onClick={()=>void stop()}>Stop</button></div><textarea className="editor" value={output} readOnly rows={14} placeholder="Session output"/><div className="formRow"><input value={input} onChange={e=>setInput(e.target.value)} placeholder="Input sent to the active session"/><button className="primary" disabled={!session} onClick={()=>void write()}>Send</button><button className="ghost" disabled={!session} onClick={()=>void read()}>Read output</button></div>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}<p className="hint">PTY mode is the terminal-capable path for interactive shells, resize and TUIs; the bounded pipe mode remains available for programs that do not need terminal semantics. New PTY sessions also keep bounded durable scrollback under the VSN data directory.</p></section><section className="panel"><div className="panelHead"><div><span className="kicker">Durable evidence</span><h3>PTY scrollback journals</h3></div><Badge ok={scrollbacks.length>0} label={`${scrollbacks.length} journals`}/></div><div className="buttonRow"><button className="ghost" onClick={()=>void loadScrollbacks()}>Refresh journals</button><button className="ghost" disabled={!scrollId} onClick={()=>void readScrollback()}>Read next chunk</button><button className="danger" disabled={!scrollId} onClick={()=>void removeScrollback()}>Remove inactive journal</button></div><div className="formGrid"><label>Journal<select value={scrollId} onChange={(e:ChangeEvent<HTMLSelectElement>)=>{setScrollId(e.target.value);setScrollOffset(0);setScrollText('')}}><option value="">Select journal</option>{scrollbacks.map(j=><option key={j.session_id} value={j.session_id}>{j.session_id} · {j.bytes} bytes · {j.active?'active':'inactive'}</option>)}</select></label><label>Offset<input type="number" min={0} value={scrollOffset} onChange={(e:ChangeEvent<HTMLInputElement>)=>setScrollOffset(Math.max(0,Number(e.target.value)||0))}/></label></div>{scrollText&&<pre className="terminalOutput">{scrollText}</pre>}<p className="hint">Scrollback survives Agent restart, but VSN never recreates the previous PTY or replays shell input automatically.</p></section></>}
function Networking(){const[domain,setDomain]=useState('workforce.test');const[port,setPort]=useState('8000');const[plan,setPlan]=useState<any>(null);async function run(){setPlan(await call('domain.plan',{domain,port:Number(port),tls:true}))}return <section className="panel"><div className="panelHead"><div><span className="kicker">Local routing</span><h3>.test domain planner</h3></div><Badge ok label="TLS-ready"/></div><div className="formGrid"><label>Domain<input value={domain} onChange={e=>setDomain(e.target.value)}/></label><label>Upstream port<input value={port} onChange={e=>setPort(e.target.value)}/></label></div><button className="primary" onClick={()=>void run()}>Validate plan</button>{plan&&<JsonView value={plan}/>}<p className="hint">Hosts-file mutation, local CA installation and Caddy binding require the elevated network helper instead of normal IPC permissions.</p></section>}
function RemotePanel({config}:{config:RemoteConfig|null}){const[url,setUrl]=useState(config?.control_plane_url??'');const[key,setKey]=useState(config?.control_plane_public_key??'');const[enabled,setEnabled]=useState(config?.enabled??false);const[allowTerminal,setAllowTerminal]=useState(config?.allow_remote_terminal??false);const[allowFileWrite,setAllowFileWrite]=useState(config?.allow_remote_file_write??false);const[allowDbQuery,setAllowDbQuery]=useState(config?.allow_remote_database_query??false);const[allowInteractivePreview,setAllowInteractivePreview]=useState(config?.allow_remote_preview_interactive??false);const[nonce,setNonce]=useState('');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');useEffect(()=>{if(config){setUrl(config.control_plane_url??'');setKey(config.control_plane_public_key??'');setEnabled(config.enabled);setAllowTerminal(config.allow_remote_terminal??false);setAllowFileWrite(config.allow_remote_file_write??false);setAllowDbQuery(config.allow_remote_database_query??false);setAllowInteractivePreview(config.allow_remote_preview_interactive??false)}},[config]);async function save(){setErr('');try{setResult(await call('remote.configure',{url,public_key:key,enabled,poll_interval_ms:2500,allow_remote_terminal:allowTerminal,allow_remote_file_write:allowFileWrite,allow_remote_database_query:allowDbQuery,allow_remote_preview_interactive:allowInteractivePreview}))}catch(e){setErr(String(e))}}async function enroll(){setErr('');try{setResult(await call('remote.enroll',{pairing_nonce:nonce}))}catch(e){setErr(String(e))}}return <><section className="hero remoteHero"><div><span className="kicker">Outbound only</span><h2>{enabled?'Remote channel enabled':'Remote channel disabled'}</h2><p>The Agent initiates the connection and verifies signed, short-lived, device-bound commands before local policy dispatch. Delivery retries are idempotent through the Agent result cache.</p></div><Badge ok={enabled} label={enabled?'Configured':'Local only'}/></section><section className="panel"><div className="panelHead"><div><span className="kicker">Machine pairing</span><h3>Control Plane configuration</h3></div></div><div className="formGrid"><label>Control Plane URL<input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://control.example.com"/></label><label>Control Plane public key<input value={key} onChange={e=>setKey(e.target.value)} placeholder="Base64 Ed25519 public key"/></label><label>Pairing nonce<input value={nonce} onChange={e=>setNonce(e.target.value)} placeholder="pair_..."/></label><label className="check"><input type="checkbox" checked={enabled} onChange={e=>setEnabled(e.target.checked)}/> Enable outbound polling</label><label className="check"><input type="checkbox" checked={allowTerminal} onChange={e=>setAllowTerminal(e.target.checked)}/> Allow scoped remote terminal commands</label><label className="check"><input type="checkbox" checked={allowFileWrite} onChange={e=>setAllowFileWrite(e.target.checked)}/> Allow scoped remote file writes</label><label className="check"><input type="checkbox" checked={allowDbQuery} onChange={e=>setAllowDbQuery(e.target.checked)}/> Allow scoped remote database queries</label><label className="check"><input type="checkbox" checked={allowInteractivePreview} onChange={e=>setAllowInteractivePreview(e.target.checked)}/> Allow interactive remote preview WebSocket bridge</label></div><div className="buttonRow"><button className="primary" onClick={()=>void save()}>Save remote config</button><button className="ghost" disabled={!nonce} onClick={()=>void enroll()}>Enroll device</button></div>{err&&<div className="error">{err}</div>}{result&&<JsonView value={result}/>}</section></>}


function ContainerRegistry(){const[backend,setBackend]=useState('docker');const[source,setSource]=useState('local/app:latest');const[target,setTarget]=useState('registry.example.com/team/app:latest');const[push,setPush]=useState(false);const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');async function publish(){setErr('');try{setResult(await call('container.registry-publish',{backend,source,target,push}))}catch(e){setErr(String(e))}}return <section className="panel"><div className="panelHead"><div><span className="kicker">Registry publishing</span><h3>Tag / push using existing Docker or Podman auth</h3></div><Badge ok label="No registry password in VSN request"/></div><div className="formGrid"><label>Backend<select value={backend} onChange={(e:ChangeEvent<HTMLSelectElement>)=>setBackend(e.target.value)}><option>docker</option><option>podman</option></select></label><label>Source image<input value={source} onChange={(e:ChangeEvent<HTMLInputElement>)=>setSource(e.target.value)}/></label><label>Registry target<input value={target} onChange={(e:ChangeEvent<HTMLInputElement>)=>setTarget(e.target.value)}/></label><label className="check"><input type="checkbox" checked={push} onChange={(e:ChangeEvent<HTMLInputElement>)=>setPush(e.target.checked)}/> Push after tag</label></div><button className="primary" onClick={()=>void publish()}>Tag / publish</button><p className="hint">VSN does not accept registry passwords on the command line. Docker/Podman existing credential context is used by the backend.</p>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section>}

function AdvancedModelAnalyzer(){const[request,setRequest]=useState('{"model":"document","documents":[{"id":1,"name":"Ada"},{"id":2,"name":null}]}');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');async function analyze(){setErr('');try{setResult(await call('database.model.analyze',JSON.parse(request)))}catch(e){setErr(String(e))}}return <section className="panel"><div className="panelHead"><div><span className="kicker">Advanced data models</span><h3>Document / KV / Vector / Graph / Search / Time-series / Column analyzer</h3></div><Badge ok label="Bounded local analysis"/></div><label className="stacked">Model sample JSON<textarea value={request} onChange={(e:ChangeEvent<HTMLTextAreaElement>)=>setRequest(e.target.value)} rows={8}/></label><button className="primary" onClick={()=>void analyze()}>Analyze model sample</button><p className="hint">Document, key-value, vector, graph, search, time-series and wide-column samples are normalized through one bounded schema-driven analyzer with type/distribution/integrity warnings.</p>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section>}

function DatabaseJobs(){
 const[connectionJson,setConnectionJson]=useState('{"engine":"postgresql","host":"127.0.0.1","port":5432,"user":"postgres","database":"postgres","credential_file":null,"service":null}');
 const[sql,setSql]=useState('SELECT pg_sleep(10), now()');const[jobs,setJobs]=useState<any[]>([]);const[selected,setSelected]=useState('');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');const[artifactOffset,setArtifactOffset]=useState(0);const[artifactText,setArtifactText]=useState('');
 async function refresh(){setErr('');try{const rows=await call<any[]>('database.cli.job.list',{});setJobs(rows);if(!selected&&rows[0])setSelected(rows[0].job_id)}catch(e){setErr(String(e))}}
 async function start(){setErr('');try{const connection=JSON.parse(connectionJson);const row=await call<any>('database.cli.job.start',{connection,sql});setResult(row);setSelected(row.job_id);setArtifactOffset(0);setArtifactText('');await refresh()}catch(e){setErr(String(e))}}
 async function status(){if(!selected)return;setErr('');try{setResult(await call('database.cli.job.status',{job_id:selected}));await refresh()}catch(e){setErr(String(e))}}
 async function cancel(){if(!selected)return;setErr('');try{setResult(await call('database.cli.job.cancel',{job_id:selected}));await refresh()}catch(e){setErr(String(e))}}
 async function readArtifact(){if(!selected)return;setErr('');try{const chunk=await call<any>('database.cli.job.output',{job_id:selected,offset:artifactOffset,max_bytes:262144});const raw=atob(chunk.payload_base64||'');const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));setArtifactText(prev=>prev+new TextDecoder().decode(bytes));setArtifactOffset(Number(chunk.next_offset||artifactOffset));setResult(chunk)}catch(e){setErr(String(e))}}
 async function removeArtifact(){if(!selected)return;setErr('');try{await call('database.cli.job.output-remove',{job_id:selected});setArtifactOffset(0);setArtifactText('');await status()}catch(e){setErr(String(e))}}
 useEffect(()=>{void refresh()},[]);
 return <section className="panel"><div className="panelHead"><div><span className="kicker">Durable cancellable reads</span><h3>External database query jobs</h3></div><Badge ok label="No shell / actual process kill"/></div><label className="stacked">Connection JSON<textarea value={connectionJson} onChange={(e:ChangeEvent<HTMLTextAreaElement>)=>setConnectionJson(e.target.value)} rows={4}/></label><label className="stacked">Read-only SQL<textarea value={sql} onChange={(e:ChangeEvent<HTMLTextAreaElement>)=>setSql(e.target.value)} rows={4}/></label><div className="buttonRow"><button className="primary" onClick={()=>void start()}>Start job</button><button className="ghost" onClick={()=>void refresh()}>Refresh</button><button className="ghost" disabled={!selected} onClick={()=>void status()}>Status</button><button className="danger" disabled={!selected} onClick={()=>void cancel()}>Cancel</button><button className="ghost" disabled={!selected} onClick={()=>void readArtifact()}>Read result chunk</button><button className="danger" disabled={!selected} onClick={()=>void removeArtifact()}>Remove result artifact</button></div><div className="formGrid"><label>Job<select value={selected} onChange={(e:ChangeEvent<HTMLSelectElement>)=>{setSelected(e.target.value);setArtifactOffset(0);setArtifactText('')}}><option value="">Select job</option>{jobs.map(j=><option value={j.job_id} key={j.job_id}>{j.job_id} · {j.engine} · {j.state}{j.artifact?` · ${j.artifact.bytes} bytes`:''}</option>)}</select></label><label>Artifact offset<input type="number" min={0} value={artifactOffset} onChange={(e:ChangeEvent<HTMLInputElement>)=>setArtifactOffset(Math.max(0,Number(e.target.value)||0))}/></label></div><p className="hint">Jobs are journaled before execution. Agent restart marks an orphaned Running journal Interrupted without re-executing it. Successful output may be spooled up to 64 MiB with SHA-256 and read back in bounded chunks.</p>{artifactText&&<pre className="terminalOutput">{artifactText}</pre>}{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section>
}


function NativePostgresJobs(){
 const[connection,setConnection]=useState('host=localhost user=postgres dbname=postgres');const[sql,setSql]=useState('SELECT pg_sleep(10), now()');const[jobs,setJobs]=useState<any[]>([]);const[selectedJob,setSelectedJob]=useState('');const[txn,setTxn]=useState('');const[result,setResult]=useState<any>(null);const[err,setErr]=useState('');
 async function refresh(){setErr('');try{const rows=await call<any[]>('database.native.postgres.job.list',{});setJobs(rows);if(!selectedJob&&rows[0])setSelectedJob(rows[0].job_id)}catch(e){setErr(String(e))}}
 async function start(){setErr('');try{const row=await call<any>('database.native.postgres.job.start',{connection_string:connection,sql});setSelectedJob(row.job_id);setResult(row);await refresh()}catch(e){setErr(String(e))}}
 async function cancel(){if(!selectedJob)return;setErr('');try{setResult(await call('database.native.postgres.job.cancel',{job_id:selectedJob}));await refresh()}catch(e){setErr(String(e))}}
 async function jobStatus(){if(!selectedJob)return;setErr('');try{setResult(await call('database.native.postgres.job.status',{job_id:selectedJob}));await refresh()}catch(e){setErr(String(e))}}
 async function txnStart(){setErr('');try{const row=await call<any>('database.native.postgres.txn.start',{connection_string:connection,ttl_seconds:30});setTxn(row.transaction_id);setResult(row)}catch(e){setErr(String(e))}}
 async function txnQuery(){if(!txn)return;setErr('');try{setResult(await call('database.native.postgres.txn.query',{transaction_id:txn,sql}))}catch(e){setErr(String(e))}}
 async function txnStatus(){if(!txn)return;setErr('');try{setResult(await call('database.native.postgres.txn.status',{transaction_id:txn}))}catch(e){setErr(String(e))}}
 async function txnClose(commit=false){if(!txn)return;setErr('');try{setResult(await call('database.native.postgres.txn.close',{transaction_id:txn,commit}));setTxn('')}catch(e){setErr(String(e))}}
 useEffect(()=>{void refresh()},[]);
 return <section className="panel"><div className="panelHead"><div><span className="kicker">Native PostgreSQL control</span><h3>Server cancel + read-only transaction sessions</h3></div><Badge ok label="Loopback / read-only"/></div><div className="formGrid"><label>Connection<input value={connection} onChange={e=>setConnection(e.target.value)}/></label><label>Job<select value={selectedJob} onChange={e=>setSelectedJob(e.target.value)}><option value="">Select job</option>{jobs.map(j=><option key={j.job_id} value={j.job_id}>{j.job_id} · {j.state}{j.cancel_requested?' · cancel requested':''}</option>)}</select></label><label>Transaction<input value={txn} readOnly placeholder="No open transaction"/></label></div><label className="stacked">Read-only SQL<textarea value={sql} onChange={e=>setSql(e.target.value)} rows={4}/></label><div className="buttonRow"><button className="primary" onClick={()=>void start()}>Start native job</button><button className="ghost" onClick={()=>void refresh()}>Refresh jobs</button><button className="ghost" disabled={!selectedJob} onClick={()=>void jobStatus()}>Job status</button><button className="danger" disabled={!selectedJob} onClick={()=>void cancel()}>Server cancel request</button><button className="primary" onClick={()=>void txnStart()}>Begin READ ONLY</button><button className="ghost" disabled={!txn} onClick={()=>void txnQuery()}>Query transaction</button><button className="ghost" disabled={!txn} onClick={()=>void txnStatus()}>Txn status</button><button className="ghost" disabled={!txn} onClick={()=>void txnClose(true)}>Commit</button><button className="danger" disabled={!txn} onClick={()=>void txnClose(false)}>Rollback</button></div><p className="hint">Native PostgreSQL jobs request server-side cancellation through PostgreSQL's cancellation protocol. Transaction sessions are BEGIN READ ONLY, bounded by TTL, statement count and server statement/idle timeouts. They are in-memory and intentionally not reconstructed after Agent restart.</p>{result&&<JsonView value={result}/>} {err&&<div className="error">{err}</div>}</section>
}
